"""Read compilation databases generated by the TF-M/RSE CMake build.

Output lookup supports the single '-o <object>' pair emitted by the in-tree
toolchains. Additional flags must not introduce another standalone '-o', even
as an operand or forwarded argument. Joined/long output options and response
file expansion are outside this build-system interface's input contract.
"""

import os
import json
import argparse
import ntpath
import shlex
import subprocess
import sys

import logging
logger = logging.getLogger("TF-M.{}".format(__name__))


def _windows_path(path):
    return os.name == 'nt' or bool(ntpath.splitdrive(os.fspath(path))[0])


def _absolute_path(path, directory):
    path_module = ntpath if _windows_path(directory) or _windows_path(path) else os.path
    return path_module.normpath(path_module.join(directory, path))


def _path_key(path, directory):
    """Return an absolute lexical path key for output comparisons."""
    # Do not resolve symlinks: compilation database paths are lexical paths.
    path = _absolute_path(path, directory)
    return ntpath.normcase(path) if _windows_path(path) else path


def _split_windows_command(command):
    """Split Windows compiler arguments without treating path separators as escapes."""
    arguments = []
    index = 0
    while index < len(command):
        while index < len(command) and command[index] in ' \t':
            index += 1
        if index == len(command):
            break
        argument = []
        quoted = False
        while index < len(command):
            char = command[index]
            if char in ' \t' and not quoted:
                break
            if char == '\\':
                start = index
                while index < len(command) and command[index] == '\\':
                    index += 1
                count = index - start
                if index == len(command) or command[index] != '"':
                    argument.append('\\' * count)
                    continue
                argument.append('\\' * (count // 2))
                if count % 2:
                    argument.append('"')
                    index += 1
                    continue
                char = '"'
            if char == '"':
                if quoted and command[index:index + 2] == '""':
                    argument.append('"')
                    index += 2
                    continue
                quoted = not quoted
            else:
                argument.append(char)
            index += 1
        arguments.append(''.join(argument))
    return arguments


def _arguments(entry):
    if 'arguments' in entry:
        arguments = entry['arguments']
    elif _windows_path(entry['directory']):
        arguments = _split_windows_command(entry['command'])
    else:
        arguments = shlex.split(entry['command'])
    if not arguments:
        raise ValueError(f"Empty compile command for {entry['file']!r}")
    return arguments


def _option_values(arguments, options):
    arguments = iter(arguments[1:])
    for argument in arguments:
        for option in options:
            if argument == option:
                try:
                    yield next(arguments)
                except StopIteration:
                    raise ValueError(f"Missing value for compiler option {option}") from None
                break
            if argument.startswith(option):
                yield argument[len(option):]
                break


def _compiler_output(arguments):
    """Read the single '-o <object>' pair emitted by TF-M/RSE's CMake rules."""
    # The module's input contract lets us find this token without interpreting
    # arbitrary compiler options or their operands.
    positions = [index for index, value in enumerate(arguments[1:], 1) if value == '-o']
    if not positions:
        return None
    if len(positions) != 1:
        raise ValueError("Expected a single '-o <object>' in the CMake compile command")
    index = positions[0] + 1
    if index == len(arguments) or not arguments[index]:
        raise ValueError("Missing output filename after '-o' in the CMake compile command")
    return arguments[index]


def _output_paths(entry, database_dir):
    """Resolve the compiler output or fall back to optional output metadata."""
    arguments = _arguments(entry)
    directory = _absolute_path(entry['directory'], database_dir)
    output = _compiler_output(arguments)

    if output is not None:
        # Compiler outputs are relative to the working directory and take
        # precedence over metadata, which can be stale.
        return {_path_key(output, directory)}
    if 'output' in entry:
        # CMake's Makefile generator can record metadata relative to the build
        # root instead of the working directory. Allow either convention.
        return {_path_key(entry['output'], base)
                for base in (directory, database_dir)}
    return set()


def _get_compile_entry(compile_commands_file, c_file=None, *, output_file=None):
    if (c_file is None) == (output_file is None):
        raise ValueError('Specify exactly one of c_file and output_file')
    with open(compile_commands_file, 'rt', encoding='utf-8') as f:
        compile_commands = json.load(f)

    if output_file is None:
        # Preserve the existing source-substring API, including its first-match
        # selection for callers whose source is compiled by multiple targets.
        matches = [entry for entry in compile_commands if os.fspath(c_file) in entry['file']]
    else:
        database_dir = os.path.dirname(os.path.abspath(compile_commands_file))
        requested = _path_key(output_file, database_dir)
        matches = []
        for entry in compile_commands:
            if requested in _output_paths(entry, database_dir):
                matches.append(entry)
        if len(matches) > 1:
            raise ValueError(f"Ambiguous compile command for output {str(output_file)!r} "
                             f"in {str(compile_commands_file)!r}: {len(matches)} matches")
    if not matches:
        requested = c_file if output_file is None else output_file
        raise ValueError(f"No compile command for {str(requested)!r} "
                         f"in {str(compile_commands_file)!r}")
    return matches[0]


def get_compile_command(compile_commands_file, c_file=None, *, output_file=None):
    """Select a TF-M/RSE CMake entry by source substring or exact output path.

    Relative output_file paths are relative to the compilation database directory.
    Output lookups must identify exactly one entry.
    """
    entry = _get_compile_entry(compile_commands_file, c_file, output_file=output_file)
    if 'arguments' not in entry:
        return entry['command']
    quote = subprocess.list2cmdline if _windows_path(entry['directory']) else shlex.join
    return quote(_arguments(entry))


def get_includes(compile_commands_file, c_file=None, *, output_file=None):
    entry = _get_compile_entry(compile_commands_file, c_file, output_file=output_file)
    arguments = _arguments(entry)
    # Preserve the existing user-before-system include search order.
    includes = list(_option_values(arguments, ('-I',)))
    includes.extend(_option_values(arguments, ('-isystem',)))
    if output_file is None:
        return includes
    database_dir = os.path.dirname(os.path.abspath(compile_commands_file))
    directory = _absolute_path(entry['directory'], database_dir)
    return [_absolute_path(include, directory) for include in includes]


def get_defines(compile_commands_file, c_file=None, *, output_file=None):
    entry = _get_compile_entry(compile_commands_file, c_file, output_file=output_file)
    return list(_option_values(_arguments(entry), ('-D',)))


def get_compiler(compile_commands_file, c_file=None, *, output_file=None):
    entry = _get_compile_entry(compile_commands_file, c_file, output_file=output_file)
    return _arguments(entry)[0]


def main():
    parser = argparse.ArgumentParser(allow_abbrev=False)
    parser.add_argument("--compile_commands_file", help="path to compile_command.json", required=True)
    parser.add_argument("--c_file", help="name of the c file to take", required=True)
    parser.add_argument("--log_level", help="log level", required=False, default="ERROR", choices=logging._levelToName.values())
    args = parser.parse_args()
    logging.getLogger("TF-M").setLevel(args.log_level)
    logger.addHandler(logging.StreamHandler())

    print(get_compile_command(args.compile_commands_file, args.c_file))
    print(get_includes(args.compile_commands_file, args.c_file))
    print(get_defines(args.compile_commands_file, args.c_file))


if __name__ == "__main__":
    sys.exit(main())
